{
  "severity": "critical",
  "network_observations": [
    {"ip": "10.40.5.18", "inferred_role": "corporate_file_server_being_encrypted", "first_seen": "2028-08-14T01:05:42+0200", "last_seen": "2028-08-14T01:16:22+0200", "agent_name": "FS-SERVER-01"},
    {"ip": "10.40.2.10", "inferred_role": "domain_controller_admin_pivot_source", "first_seen": "2028-08-14T01:05:42+0200", "last_seen": "2028-08-14T01:05:42+0200", "agent_name": "DC-CORP-01"}
  ],
  "attack_progression": [
    {"step": 1, "tactic": "Lateral Movement (Already Inside)", "technique": "T1021.002", "what_happened": "At 2028-08-14 01:05:42 CEST, Windows Security Event 4624 fired on FS-SERVER-01 (10.40.5.18) — targetUserName=administrator, logonType=3 (Network — typical SMB/RPC), ipAddress=10.40.2.10 (DC-CORP-01). The attacker is using the built-in domain administrator account that is ALREADY compromised and is pivoting FROM the domain controller. The DC being the pivot source is highly anomalous — DCs should not initiate outbound interactive admin sessions to member servers; this strongly suggests DC-CORP-01 itself is compromised (or the attacker has acquired admin Kerberos tickets, possibly via DCSync / Golden Ticket / NTDS dump performed in an earlier intrusion phase that has not yet been observed in this alert window).", "chain_reason": "Windows Security Event 4624 (rule.id 60103) with logonType=3 from internal DC IP. The chained alert ties this 4624 to the subsequent Sysmon Event 1 sequence on the same host under the same user within 6 minutes.", "first_seen": "2028-08-14T01:05:42+0200"},
    {"step": 2, "tactic": "Execution / Remote Shell", "technique": "T1059.003 + T1021.002", "what_happened": "At 01:08:18, Sysmon Event 1 on FS-SERVER-01 recorded cmd.exe spawned with parentImage=services.exe under user=administrator — the canonical PsExec / remote-service-execution shell pattern (PsExec installs a temporary service that spawns cmd.exe as a child of services.exe). At 01:09:31, the attacker ran 'whoami /priv' under that cmd.exe to verify the elevated privilege set (SeBackupPrivilege + SeRestorePrivilege + SeTakeOwnershipPrivilege are needed for VSS manipulation).", "chain_reason": "Sysmon Event 1 (rule.id 61603) with image=cmd.exe + parentImage=services.exe is the PsExec / wmiexec signature.", "first_seen": "2028-08-14T01:08:18+0200"},
    {"step": 3, "tactic": "Impact — Inhibit System Recovery", "technique": "T1490", "what_happened": "Between 01:12:05 and 01:12:13 (8 seconds), the attacker executed FOUR consecutive recovery-inhibition commands under cmd.exe on FS-SERVER-01: (a) 01:12:05 — 'vssadmin.exe delete shadows /all /quiet' (deletes ALL Volume Shadow Copies — the backup-snapshot service Windows uses to enable file restore + System Restore), (b) 01:12:06 — 'wbadmin.exe delete catalog -quiet' (deletes the Windows Backup catalog — the backup-set index, without which Windows Backup cannot enumerate / restore historical backups), (c) 01:12:08 — 'powershell.exe -Command \"Get-WmiObject Win32_ShadowCopy | Remove-WmiObject\"' (WMI-based shadow-copy enumeration + deletion — catches shadow copies that vssadmin's /all flag may have missed, e.g., on non-system drives), (d) 01:12:10 — 'bcdedit.exe /set {default} recoveryenabled No' followed at 01:12:13 by 'bcdedit.exe /set {default} bootstatuspolicy ignoreallfailures' (disables Windows Recovery Environment + automatic boot-failure recovery). This is the canonical pre-ransomware recovery-inhibition sequence — the attacker is removing EVERY restore option before encryption begins. The 8-second compression confirms this is a scripted ransomware preparation, not human admin operation.", "chain_reason": "Sysmon Event 1 sequence with image in (vssadmin.exe, wbadmin.exe, powershell.exe, bcdedit.exe) + parentImage=cmd.exe + user=administrator within a sub-10-second window = T1490 Inhibit System Recovery signature, mapped to MITRE rule.mitre.id=T1490.", "first_seen": "2028-08-14T01:12:05+0200"},
    {"step": 4, "tactic": "Impact — Data Encryption for Impact (IN PROGRESS)", "technique": "T1486", "what_happened": "At 01:14:48 — 2 minutes 35 seconds after the recovery-inhibition burst — FS-SERVER-01 began a MASSIVE file-create burst on the D:\\Shares\\Finance\\ share: Sysmon Event 11 fired ~2,800 times in approximately 90 seconds with targetFilename matching the pattern *.locked (attacker ransomware extension). The rate (~31 files/sec) is ~10,000× the FS-SERVER-01 baseline. At 01:16:22, a final Event 11 fired with targetFilename=D:\\Shares\\Finance\\README_RECOVER.txt — the ransom note drop, signaling the encryption of this share is functionally complete. RANSOMWARE IS ACTIVELY ENCRYPTING THE FILE SERVER RIGHT NOW.", "chain_reason": "Sysmon Event 11 (rule.id 61613) high-rate-burst-on-share signature: ~2,800 file creates in 90s on the same UNC path under user=administrator, with targetFilename extension changing to *.locked + final README_RECOVER.txt drop = textbook ransomware encryption + ransom-note signature.", "first_seen": "2028-08-14T01:14:48+0200"}
  ],
  "time_window": {"start": "2028-08-14T01:05:42+0200", "end": "2028-08-14T01:16:22+0200"},
  "alert_count": 11,
  "unique_steps": 4
}
